    @EventHandler( payloadType=CreateSellerEvent.class )
    public void handle( CreateSellerEvent event) {
	    LOGGER.info("handling CreateSellerEvent - " + event );
	    Seller entity = new Seller();
            entity.setSellerId( event.getSellerId() );
            entity.setName( event.getName() );
            entity.setSellerCode( event.getSellerCode() );
            entity.setContactEmail( event.getContactEmail() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllSeller( entity );
    }

