    /**
     * Method to retrieve the Seller via an SellerPrimaryKey.
     * @param 	id Long
     * @return 	Seller
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Seller handle( FindSellerQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getSellerId() );
    }
    
    /**
     * Method to retrieve a collection of all Sellers
     *
     * @param	query	FindAllSellerQuery 
     * @return 	List<Seller> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Seller> handle( FindAllSellerQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindSeller,
 * but only if the id matches
 *
 * @param		entity	Seller
 */
	protected void emitFindSeller( Seller entity ) {
		LOGGER.info("handling emitFindSeller" );
		
	    queryUpdateEmitter.emit(FindSellerQuery.class,
	                            query -> query.getFilter().getSellerId().equals(entity.getSellerId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllSeller
	 * 
	 * @param		entity	Seller
	 */
	protected void emitFindAllSeller( Seller entity ) {
		LOGGER.info("handling emitFindAllSeller" );
		
	    queryUpdateEmitter.emit(FindAllSellerQuery.class,
	                            query -> true,
	                            entity);
	}

